pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }
    function testFuzz_property(
        address _caller,
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public {
        vm.assume(_caller != address(0x000000000000000000000000000000000000000A));
        vm.assume(_number != c.number());
        uint64 _oldNumber = c.number();
        vm.prank(_caller);
        try c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar) {
        } catch {
        }
        if (_caller == c.DEPOSITOR_ACCOUNT()) {
            assertTrue(c.number() == _number);
        } else {
            assertTrue(c.number() == _oldNumber);
        }
    }
}
